def _process_diff(diff):
    """Convert the diff into a human readable diff string
    """
    if isinstance(diff, dict):
        return "{" + ", ".join(f"{k}: {_process_diff(v)}" for k, v in diff.items()) + "}"
    elif isinstance(diff, list):
        return "[" + ", ".join(_process_diff(v) for v in diff) + "]"
    elif isinstance(diff, tuple):
        return "(" + ", ".join(_process_diff(v) for v in diff) + ")"
    else:
        return repr(diff)


